-- Catalog metadata is migrated once; opening stock is deliberately not invented.
CREATE TABLE public.catalog_settings (
 singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
 common_price_kes integer NOT NULL CHECK (common_price_kes > 0)
);
INSERT INTO public.catalog_settings VALUES (true,2500);
CREATE TABLE public.catalog_product (
 id text PRIMARY KEY, slug text NOT NULL UNIQUE, name text NOT NULL,
 category text NOT NULL, category_slug text NOT NULL, gender text NOT NULL,
 size text NOT NULL, notes text NOT NULL, description text NOT NULL,
 images jsonb NOT NULL CHECK (jsonb_typeof(images)='array'),
 price_override_kes integer CHECK (price_override_kes > 0),
 stock integer NOT NULL DEFAULT 0 CHECK (stock >= 0),
 opened boolean NOT NULL DEFAULT false
);
CREATE TABLE public.stock_control (
 singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
 authority text NOT NULL DEFAULT 'unconfirmed' CHECK (authority IN ('unconfirmed','replacement')),
 reconciled_until timestamptz,
 approved_by text NOT NULL DEFAULT '', evidence text NOT NULL DEFAULT ''
);
INSERT INTO public.stock_control(singleton) VALUES (true);
CREATE TABLE public.stock_batch (
 id text PRIMARY KEY, digest text NOT NULL, kind text NOT NULL CHECK (kind IN ('opening','receipt','local_sale','adjustment','reconcile')),
 actor text NOT NULL, evidence text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.stock_entry (
 batch_id text NOT NULL REFERENCES public.stock_batch(id),
 product_id text NOT NULL REFERENCES public.catalog_product(id),
 delta integer NOT NULL, balance integer NOT NULL CHECK (balance >= 0),
 PRIMARY KEY (batch_id,product_id)
);
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p1','arabian-wood','Arabian Wood','Woody','woody','Unisex','100ml','Oud, cedar, warm amber','A journey through ancient souks and desert nights. Rich oud resin opens the composition, giving way to a heart of smoked cedarwood and precious resins. The base settles into warm amber and earthy musk — deeply intimate, endlessly alluring.','["img/arabian%20wood.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p2','aventus-man','Aventus Man','Luxury','luxury','Male','100ml','Bergamot, birch, oakmoss','Inspired by the great conquerors of history, this fragrance opens with an explosive burst of bergamot and blackcurrant before drifting into a smoky birch and oakmoss heart. Bold, sophisticated, and unmistakably powerful — the scent of ambition.','["img/aventus%20man.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p3','azzaro-chrome','Azzaro Chrome','Fresh','fresh','Male','100ml','Bergamot, neroli, sea breeze','Clean, bright, and effortlessly elegant. A sparkling opening of bergamot and neroli gives way to a cool aquatic heart and a dry base of oakmoss and tonka. The quintessential gentleman''s fresh — fresh for work, fresh for play.','["img/azzaro%20chrome.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p4','blue-man','Blue Man','Fresh','fresh','Male','100ml','Citrus, ginger, cedar','A crisp, invigorating blue fragrance with a modern edge. Zesty citrus and crushed ginger light up the top, while a clean woody heart of cedar and vetiver grounds the scent. Light enough for daily wear, confident enough for any occasion.','["img/blue%20man.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p5','chocolate','Chocolate','Gourmand','gourmand','Unisex','100ml','Cocoa, vanilla, brown sugar','Sinfully indulgent and utterly irresistible. Dark bittersweet cocoa opens like warm ganache, folding into a creamy vanilla and caramelised sugar heart. The base of sandalwood and musk makes it wearable all day — a sweet treat that never gets old.','["img/chocolate.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p6','eros','Eros','Spicy','spicy','Male','100ml','Mint, apple, vanilla cedar','Named for the god of love — fresh, sensual, and impossible to ignore. A cool clash of crushed mint and green apple opens boldly, while a heart of tonka bean and geranium adds warmth and sensuality. Cedar and vanilla finish the story with timeless authority.','["img/eros.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p7','guilty-woman','Guilty Woman','Floral','floral','Female','100ml','Mandarin, peach, white musk','A playfully seductive floral for the fearlessly feminine. Bright mandarin and juicy peach open the top before flowing into a lush heart of lilac and geranium. The finish is a lingering cloud of soft white musk — light, sensual, free.','["img/guilty%20woman.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p8','interlude-man','Interlude Man','Luxury','luxury','Male','100ml','Orris, amber, incense','A contemplative, deeply complex fragrance for those who think between the beats. Bitter orris and oregano clash beautifully in the opening before incense and oud rise through the heart. Amber and sandalwood hold the base in meditative warmth — powerful and poetic.','["img/interlude%20man.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p9','lost-cherry','Lost Cherry','Sweet','sweet','Unisex','100ml','Cherry, almond, tonka','Dangerously delicious. A burst of tart cherry liqueur smashes into roasted almond and warm clove in the opening — daring and addictive. A creamy tonka bean and Turkish rose heart softens the edge, while vetiver and sandalwood lend a smoky, skin-close depth.','["img/lost%20cherry.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p10','man-extreme','Man Extreme','Spicy','spicy','Male','100ml','Bergamot, pepper, warm amber','Pushed to the limit. This intense masculine fragrance opens with sharp bergamot and fiery black pepper, evolving into a bold heart of geranium and earthy vetiver. A base of warm amber and cedarwood makes it long-lasting and memorable — extreme by name, extreme by nature.','["img/man%20extreme.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p11','men-in-black','Men in Black','Woody','woody','Male','100ml','Leather, vanilla, dark musk','Dark, commanding, and magnetic. Black leather and smoky woods form an imposing opening that softens into a heart of iris and spices. Rich vanilla and benzoin anchor the base into a long, enveloping trail — the scent of quiet power and sharp style.','["img/men%20in%20black.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p12','mon-legend','Mon Legend','Fresh','fresh','Male','100ml','Bergamot, vetiver, white musk','The everyday legend. Bergamot and aquatic accords lift the opening into a clean, bright freshness. A smooth heart of rosewood and white musks carries through the day, drying down to a crisp vetiver base. Discreet confidence in a bottle.','["img/mon%20lengend.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p13','oud-ispahan','Oud Ispahan','Luxury','luxury','Unisex','100ml','Rose, oud, precious woods','A masterpiece of Oriental perfumery. Saffron and rose absolute open in gilded warmth before a rich heart of rare oud and labdanum takes hold. Patchouli and sandalwood form a velvety base that unfurls on skin for hours — the definition of effortless luxury.','["img/oud%20ispahan.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p14','rouge-540','Rouge 540','Luxury','luxury','Unisex','100ml','Jasmine, ambergris, cedar','The scent that stopped the world. An extraordinary floral amber that opens with a rush of jasmine and saffron, blooms into a rich heart of ambergris and fir resin, then settles into a cedar and musk base that becomes your own skin. There is no equivalent.','["img/rouge%20540.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p15','royal-night','Royal Night','Woody','woody','Unisex','100ml','Oud, vanilla, royal amber','When the palace lights go out and the stars take over — this is what royalty smells like. Smoky oud and saffron command the opening, softened by a heart of aged amber and florals. Vanilla and rich musks close the night in velvet warmth.','["img/royal%20night.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p16','sauvage-elixir','Sauvage Elixir','Spicy','spicy','Male','100ml','Cardamom, sandalwood, amber','The most concentrated chapter in the Sauvage saga. Cardamom and nutmeg open with smoky intensity, revealing a heart heavy with earthy licorice and warm lavender. Cold sandalwood and a glowing amber base create an almost magnetic pull — rich, lasting, and undeniably masculine.','["img/sauvage%20elixir.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p17','sauvage','Sauvage','Fresh','fresh','Male','100ml','Bergamot, pepper, vetiver','Raw, wild, and immediately iconic. Fresh Reggio bergamot collides with Sichuan pepper in the opening for an electrifying freshness. Ambroxan and vetiver pull the scent earthward into something vast and sky-wide — as open as a windswept plateau at dawn.','["img/sauvage.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p18','scandal-man','Scandal Man','Sweet','sweet','Male','100ml','Honey, grapefruit, leather','Provocative and polarising — exactly as intended. Juicy grapefruit zests up the opening while a unique honey and sage accord creates an addictive, edgy heart. Leather and patchouli give the base real character. It does not blend in. It never will.','["img/scandal%20man.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p19','splendid-vanilla','Splendid Vanilla','Gourmand','gourmand','Unisex','100ml','Vanilla, tonka, warm woods','Vanilla elevated to its highest form. Warm, creamy Madagascar vanilla opens without any sweetness overdrive, balanced beautifully by tonka bean and soft iris. A base of smooth woods and musks makes this the most wearable vanilla you''ll ever own — splendid is the only word.','["img/splendid%20vanilla.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p20','stronger-with-you-oud','Stronger with You Oud','Luxury','luxury','Male','100ml','Cardamom, oud, caramel','A bolder, darker chapter of an iconic love story. Spiced cardamom and chestnut open the top with warmth, while a Middle Eastern oud heart adds depth and gravitas. Caramelised sugar and vanilla in the base make it intimate and tender — strength wrapped in sweetness.','["img/stronger%20with%20you%20oud.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p21','tere-dh','Tere DH','Woody','woody','Male','100ml','Cedarwood, oud, dry musk','A no-nonsense woody powerhouse built for the modern man. Dry cedarwood and light bergamot open cleanly before oud and vetiver take over with quiet authority. A mineral musk base keeps it skin-close and long-lasting — a wardrobe staple.','["img/tere%20dh.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p22','tobacco-vanilla','Tobacco Vanilla','Gourmand','gourmand','Unisex','100ml','Tobacco, vanilla, brown sugar','Dark, sweet, and utterly irresistible — the cult classic reimagined. Aromatic tobacco leaf and warm spices crack open unexpectedly sweet in the opening, flowing into a rich vanilla absoluté laced with brown sugar and rum. The dry-down of benzoin and sequoia is pure indulgence.','["img/tobacco%20vanilla.jpeg"]');
INSERT INTO public.catalog_product(id,slug,name,category,category_slug,gender,size,notes,description,images) VALUES ('p23','vanilla','Vanilla','Sweet','sweet','Female','100ml','Vanilla, amber, soft musk','The purest expression of vanilla — stripped of everything it doesn''t need. Warm, creamy, and just the right amount of sweet. Soft amber adds a subtle glow to the heart, while sandalwood and clean musk in the base keep it grounded and wearable. Simple. Perfect. Timeless.','["img/vanilla.jpeg"]');

CREATE TABLE public.stock_approval (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 actor text NOT NULL, evidence text NOT NULL, valid_until timestamptz NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
